<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
if(is_post()){
    verify_csrf();$id=max(0,scalar_int($_POST['id']??0));$action=scalar_string($_POST['action']??'cancel');
    if($action==='settings'){$batch=max(1,min(100,scalar_int($_POST['batch_size']??30,30)));$maxAttempts=max(1,min(10,scalar_int($_POST['max_attempts']??5,5)));$stmt=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$stmt->execute(['product_alerts_enabled',isset($_POST['enabled'])?'1':'0']);$stmt->execute(['product_alert_batch_size',(string)$batch]);$stmt->execute(['product_alert_max_attempts',(string)$maxAttempts]);flash('success','تنظیمات پردازش هشدارها ذخیره شد.');redirect(app_url('admin/product-alerts.php'));}
    if($action==='run_now'){
        try{$result=process_product_alerts(max(1,min(100,(int)setting('product_alert_batch_size','30'))));$message=(string)($result['message']??'پردازش انجام شد.').' بررسی: '.fa_number((int)($result['checked']??0)).'، ارسال: '.fa_number((int)($result['sent']??0)).'، خطا: '.fa_number((int)($result['failed']??0));flash(!empty($result['paused'])?'error':'success',$message);}catch(Throwable $exception){log_error($exception);flash('error',$exception->getMessage());}redirect(app_url('admin/product-alerts.php'));}
    if($action==='cancel')db()->prepare("UPDATE product_alerts SET status='cancelled',lock_token=NULL,locked_at=NULL WHERE id=? AND status IN ('pending','processing','failed')")->execute([$id]);
    if($action==='retry')db()->prepare("UPDATE product_alerts SET status='pending',attempts=0,next_attempt_at=NOW(),last_error=NULL,lock_token=NULL,locked_at=NULL WHERE id=?")->execute([$id]);
    flash('success','وضعیت هشدار به‌روزرسانی شد.');redirect(app_url('admin/product-alerts.php'));
}
$status=scalar_string($_GET['status']??'');$type=scalar_string($_GET['type']??'');$where=[];$params=[];if(isset(product_alert_status_labels()[$status])){$where[]='a.status=?';$params[]=$status;}if(isset(product_alert_type_labels()[$type])){$where[]='a.alert_type=?';$params[]=$type;}$sql=$where?' WHERE '.implode(' AND ',$where):'';
$stmt=db()->prepare('SELECT a.*,p.title,p.sku,pv.title_suffix variant_title FROM product_alerts a JOIN products p ON p.id=a.product_id LEFT JOIN product_variants pv ON pv.id=a.variant_id'.$sql.' ORDER BY a.id DESC LIMIT 500');$stmt->execute($params);$rows=$stmt->fetchAll();$stats=db()->query('SELECT status,COUNT(*) count FROM product_alerts GROUP BY status')->fetchAll(PDO::FETCH_KEY_PAIR);
$readiness=product_alert_sms_readiness();$lastRun=(string)setting('product_alert_last_run_at','');$lastResult=(string)setting('product_alert_last_result','');$centralCronCommand=central_cron_cli_command('/usr/local/bin/php');
$adminPage='alerts';$adminTitle='هشدار موجودی و قیمت';require __DIR__.'/partials/header.php';?>
