<form method="post" class="card"><?=csrf_field()?><input type="hidden" name="action" value="settings"><h2>تنظیمات پردازش</h2><div class="form-grid"><div class="field"><label><input type="checkbox" name="enabled" value="1" <?=(string)setting('product_alerts_enabled','1')==='1'?'checked':''?>> ثبت هشدار در سایت فعال باشد</label></div><div class="field"><label>تعداد هر اجرای Cron</label><input type="number" name="batch_size" min="1" max="100" value="<?=e(setting('product_alert_batch_size','30'))?>"></div><div class="field"><label>حداکثر تلاش مجدد</label><input type="number" name="max_attempts" min="1" max="10" value="<?=e(setting('product_alert_max_attempts','5'))?>"></div><div class="field full"><label>دستور Cron مرکزی؛ فقط همین یک Cron را هر ۱۰ دقیقه اجرا کنید</label><div class="codebox" dir="ltr"><?=e($centralCronCommand)?></div><small><a href="<?=e(app_url('admin/system-health.php'))?>">مشاهده سلامت سایت و نتیجه آخرین اجرای مرکزی</a></small></div></div><button class="btn btn-primary">ذخیره تنظیمات</button></form>
<div class="stats-grid"><?php foreach(product_alert_status_labels() as $key=>$label):?><div class="stat-card"><span><?=e($label)?></span><strong><?=fa_number((int)($stats[$key]??0))?></strong></div><?php endforeach?></div>
