<div class="table-wrap"><table><thead><tr><th>محصول</th><th>موبایل</th><th>نوع</th><th>قیمت مبنا / هدف</th><th>وضعیت</th><th>تلاش</th><th>آخرین خطا</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($row['title'])?></strong><?php if($row['variant_title']):?><br><small><?=e($row['variant_title'])?></small><?php endif?><br><small dir="ltr"><?=e($row['sku'])?></small></td><td dir="ltr"><?=e($row['phone'])?></td><td><?=e(product_alert_type_labels()[$row['alert_type']]??$row['alert_type'])?></td><td><?=fa_number(format_price((int)$row['baseline_price']))?><?php if($row['target_price']!==null):?><br><small>هدف: <?=fa_number(format_price((int)$row['target_price']))?></small><?php endif?></td><td><?=e(product_alert_status_labels()[$row['status']]??$row['status'])?></td><td><?=fa_number((int)$row['attempts'])?> / <?=fa_number((int)$row['max_attempts'])?></td><td><small><?=e($row['last_error']?:'—')?></small></td><td><?php if(in_array($row['status'],['pending','processing','failed'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="action" value="cancel"><button class="btn btn-danger btn-sm">لغو</button></form><?php endif?><?php if(in_array($row['status'],['failed','cancelled'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="action" value="retry"><button class="btn btn-secondary btn-sm">تلاش مجدد</button></form><?php endif?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8">هشداری ثبت نشده است.</td></tr><?php endif?></tbody></table></div>
